import{_ as a,o as n,c as i,a6 as l}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"第十一章：工程化（Serving）","description":"从 Bit 到 AGI 专栏 · 生产级 LLM 部署 · 共 15 篇","frontmatter":{"title":"第十一章：工程化（Serving）","description":"从 Bit 到 AGI 专栏 · 生产级 LLM 部署 · 共 15 篇","source":"https://daiw.org/manual/bit-to-agi/11-engineering"},"headers":[],"relativePath":"manual/llm/bit-to-agi/11-engineering.md","filePath":"manual/llm/bit-to-agi/11-engineering.md"}'),t={name:"manual/llm/bit-to-agi/11-engineering.md"};function r(o,e,g,s,m,u){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第十一章-工程化-serving" tabindex="-1">第十一章：工程化（Serving） <a class="header-anchor" href="#第十一章-工程化-serving" aria-label="Permalink to &quot;第十一章：工程化（Serving）&quot;">​</a></h1><blockquote><p>从 Bit 到 AGI 专栏 · 生产级 LLM 部署 · 共 15 篇</p></blockquote><p>第十章你在单卡上训出了模型；本章把它变成<strong>生产服务</strong>——吞吐从 <strong>~200 tok/s</strong> 拉到 <strong>~3 000+ tok/s</strong>，TTFT 压在 <strong>亚秒级</strong>，并接上 Gateway、可观测性、扩缩容与成本治理。读完本章，你会用 QPS、P95 延迟和 $/1M tokens 这些尺子评估任意 LLM 部署方案。</p><h2 id="本章目录" tabindex="-1">本章目录 <a class="header-anchor" href="#本章目录" aria-label="Permalink to &quot;本章目录&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/vllm">vLLM</a> — PagedAttention 与连续批处理，开源 serving 默认栈</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/sglang">SGLang</a> — RadixAttention 前缀缓存与结构化生成</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/tensorrt-llm">TensorRT-LLM</a> — NVIDIA 编译级推理与 FP8/INT4</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/deepspeed">DeepSpeed</a> — ZeRO 训练与 MII/FastGen 推理</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/megatron">Megatron</a> — 千卡预训练的 TP/PP/EP 并行</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/ray">Ray</a> — 分布式 replica 与异构 pipeline</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/kubernetes">Kubernetes</a> — GPU Pod、HPA 与滚动发布</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/litellm">LiteLLM</a> — 统一百种 API 的路由与预算</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/gateway">Gateway</a> — 鉴权、限流与 Canary 路由</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/observability">可观测性</a> — TTFT/TPOT、Prometheus 与 OTel</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/autoscaling">自动扩缩容</a> — KEDA 与 GPU 弹性</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/model-registry">模型注册表</a> — 版本、stage 与 lineage</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/ab-testing">A/B 测试</a> — 在线实验与 shadow 流量</li><li><a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/cost-governance">成本治理</a> — Token 预算与 FinOps</li></ul><p>建议按顺序阅读：先推理引擎（vLLM → SGLang → TensorRT-LLM），再训练并行栈（DeepSpeed → Megatron），然后编排（Ray → K8s），最后平台层（LiteLLM → Gateway → 可观测性 → 扩缩容 → 注册表 → A/B → 成本）。全部读完后请参阅<a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/chapter-summary">第十一章总结</a>。</p>',6)])])}const b=a(t,[["render",r]]);export{h as __pageData,b as default};
